import time

from ..exceptions import ApnNotProvidedError, NoIpError


def get_at_ue_ip(ue_pc, ue_id, logger, apn=None):
    """
    Get IP address of UE
    :param ue_pc: Rpc object responsible for HTTP/HTTPS request
    :param ue_id: COM port
    :param logger: logger object
    :param apn: APN address assigned of UE
    :return: UE IP as string
    """
    atcmd_ue_ips = ue_pc.get_ue_info(ue_id=ue_id, ue_attributes=['ips'])['ips']
    logger.debug(f"getting At UE ip: {atcmd_ue_ips}")
    if atcmd_ue_ips == {}:
        raise NoIpError("At UE didn't get any IP address.")
    elif atcmd_ue_ips and apn and apn in atcmd_ue_ips:
        return atcmd_ue_ips[apn][0]
    elif atcmd_ue_ips and apn and apn not in atcmd_ue_ips:
        raise NoIpError(f"At UE didn't get IP address for \"{apn}\" APN"
                        f" - got IP for following APNs: {list(atcmd_ue_ips.keys())}")
    elif len(atcmd_ue_ips) == 1:
        return list(atcmd_ue_ips.values())[0][0]
    else:
        raise ApnNotProvidedError(f"At UE got more than one IP: {atcmd_ue_ips}"
                                  "- you have to specify which should be used.\n"
                                  "Add \"apn=<apn_name>\" param to Start Data Transfer keyword")


def get_dt_interface_with_ip_from_uepc(ue_pc, ue_id, logger, interface=None):
    """
    Get IP address of AT interface on UE PC
    :param ue_pc: Rpc object responsible for HTTP/HTTPS request
    :param ue_id: COM port
    :param logger: logger object
    :param interface: Interface on UE PC assigned AT UE
    :return: UE IP as string
    """
    atcmd_uepc_ips = ue_pc.get_ue_info(ue_id=ue_id, ue_attributes=['ips_uepc'])['ips_uepc']
    logger.debug(f"getting At UE ip: {atcmd_uepc_ips}")

    if interface:
        if interface not in atcmd_uepc_ips:
            raise NoIpError(f"A requested interface ({interface}) not found, available interfaces: "
                            f"{list(atcmd_uepc_ips.keys())}")
        return interface, atcmd_uepc_ips[interface]

    cellular_interfaces = [name for name in atcmd_uepc_ips if "cellular" in name.lower()]
    if not cellular_interfaces:
        raise NoIpError(f"No Cellular interface detected, available interfaces: {list(atcmd_uepc_ips.keys())}"
                        f"If you want to use a different interface than Cellular, "
                        f"you have to explicitly specify which should be used.\n"
                        f"Add \"interface_name=<interface_name>\" param to the configuration file.")
    if len(cellular_interfaces) == 1:
        return cellular_interfaces[0], atcmd_uepc_ips[cellular_interfaces[0]]

    raise NoIpError(f"More than one Cellular interface detected: {list(atcmd_uepc_ips.keys())} - "
                    f"you have to specify which should be used.\n"
                    f"Add \"interface_name=<interface_name>\" param to the configuration file.")


def get_at_ue_ip_with_handling_errors(ue_pc, ue_id, logger, apn=None):
    """
    Get IP address of UE
    :param ue_pc: Rpc object responsible for HTTP/HTTPS request
    :param ue_id: COM port
    :param logger: logger object
    :param apn: APN address assigned of UE
    :return: UE IP as string
    """
    try:
        return get_at_ue_ip(ue_pc=ue_pc, ue_id=ue_id, logger=logger, apn=apn)
    except NoIpError as e:
        logger.debug(f"NoIpError raised: {e}")
    except ApnNotProvidedError as e:
        logger.debug(f"ApnNotProvidedError raised: {e}")
    return None


def get_at_uepc_ip(ue_pc, ue_id, logger, interface=None, apn=None, timeout=10):
    """
    Get IP address of AT interface on UE PC and AT UE and compare them
    :param ue_pc: Rpc object responsible for HTTP/HTTPS request
    :param ue_id: COM port
    :param logger: logger object
    :param interface: Interface on UE PC assigned AT UE
    :param apn: APN address assigned of UE
    :param timeout: Timeout for getting IP address
    """
    ip_at = None
    ip_uepc = None
    end_time = time.time() + timeout
    while time.time() < end_time:
        ip_at = get_at_ue_ip_with_handling_errors(ue_pc=ue_pc, ue_id=ue_id, logger=logger, apn=apn)
        logger.debug(f"IP address retrieved from UE using AT command: {ip_at}")
        interface, ip_uepc = get_dt_interface_with_ip_from_uepc(
            ue_pc=ue_pc, ue_id=ue_id, logger=logger, interface=interface)
        logger.debug(f"IP address assigned to interface {interface} on UE PC: {ip_uepc}")
        if ip_at == ip_uepc:
            return ip_uepc
        time.sleep(1)
    logger.warning(f"IP address from interface: {interface} on UE PC: {ip_uepc} is different than IP address from "
                   f"AT command: {ip_at}. There might be a problem with running data transfer.")
    return ip_uepc


def adjust_moler_output_2_proxy_model(output, logger):
    """
    Get current statistics for specified iperf traffic

    :return: parsed output of iperf
    """
    logger.debug(f"Iperf output: {output}")
    new_iperf_out = {
        'CONNECTIONS': {},
        'INFO': '\n'.join(output.get('INFO'))
    }
    connections = output.get('CONNECTIONS', {})
    for key, value in connections.items():
        if isinstance(key, tuple):
            new_key = ';'.join(key)
            new_iperf_out['CONNECTIONS'][new_key] = value
    logger.debug(f"Formatted to json compatible iperf output: {new_iperf_out}")
    return new_iperf_out

def parse_data_transfer_statistics(bandwidth_list, logger, offset=0):
        """
        Return string with dt statistics: avg,min,max;comma-delimited list of bits/s for all intervals
        :param bandwidth_list: list of bandwidths
        :param offset: number of intervals to omit in counting statistics
        :return: tuple of (avg, min, max) and comma-delimited string of bits/s per interval
        """
        bandwidth_value_list = bandwidth_list[offset:]
        if not bandwidth_value_list:
            logger.debug('Unable to get data transfer statistics. None of the rows received.')
            return (0.0, 0.0, 0.0), ''
        avg_tput = get_average_from_list(bandwidth_value_list)
        min_tput = min(bandwidth_list)
        max_tput = max(bandwidth_list)
        list_of_bps_per_interval = get_throughput_values_as_string(bandwidth_value_list)
        return (avg_tput, min_tput, max_tput), list_of_bps_per_interval

def get_average_from_list(list_of_values, precision=2):
    """
    Calculate average value from a list with specified precision
    :param list_of_values: list of numeric values
    :param precision: number of decimal places to round to
    :return: average value rounded to given precision
    """
    return round(float(sum(list_of_values) / len(list_of_values)), precision)

def get_throughput_values_as_string(thr_value_list, delimiter=','):
    """
    Export delimited throughput values of each interval as string
    :param thr_value_list: list of throughput values
    :param delimiter: delimiter used to separate values
    :return: string of throughput values separated by delimiter
    """
    return delimiter.join([str(int(value)) for value in thr_value_list])
